public class SemanticCacheManager
{
    private readonly IRedisClient _redis;
    private readonly IEmbeddingService _embedding;
    private readonly ILogger _logger;
    private const double SIMILARITY_THRESHOLD = 0.92;
    private const int CACHE_TTL_HOURS = 168;

    public async Task<CachedResponse?> GetCachedAsync(string prompt, string modelParams, CancellationToken ct = default)
    {
        // Generate embedding for the query
        var queryEmbedding = await _embedding.GenerateAsync(prompt, ct);

        // Search Redis for semantically similar cached prompts
        var redisDb = _redis.GetDb();
        var similar = await redisDb.VectorSearchAsync(
            "semantic_cache_index", queryEmbedding, 
            new VectorSearchParameters { Threshold = SIMILARITY_THRESHOLD, K = 1 });

        if (similar.Any())
        {
            var cached = await redisDb.GetAsync($"semcache:{similar[0].Id}");
            if (cached != null)
            {
                _logger.LogInformation("Semantic cache HIT (similarity: {Sim})",
                    similar[0].Score);
                return JsonSerializer.Deserialize<CachedResponse>(cached);
            }
        }

        return null;
    }

    public async Task StoreCacheAsync(string prompt, string response, string modelParams, CancellationToken ct = default)
    {
        var embedding = await _embedding.GenerateAsync(prompt, ct);
        var key = $"semcache:{Guid.NewGuid()}";
        var entry = new CachedResponse { Prompt = prompt, Response = response };

        // Store with embedding for vector search + TTL
        await redisDb.VectorAddAsync(key, embedding, JsonSerializer.Serialize(entry),
            TimeSpan.FromHours(CACHE_TTL_HOURS));
    }
}

public class RedisRateLimiter
{
    private readonly IDatabase _redis;
    private readonly ILogger _logger;

    public async Task<bool> TryAcquireAsync(
        string apiKey, int maxRequests, TimeSpan window, CancellationToken ct = default)
    {
        var key = $"rate_limit:{apiKey}:{DateTime.UtcNow:yyyy-MM-dd-HH-mm}";

        var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        var pipeline = _redis.CreateTransaction();

        // Add current timestamp
        await pipeline.SortedSetAddAsync(key, now, now, CommandFlags.HighPriority);
        // Remove entries outside the window
        await pipeline.SortedSetRemoveRangeByScoreAsync(key, 0, now - (long)window.TotalSeconds);
        // Count remaining entries
        var count = await pipeline.SortedSetLengthAsync(key);
        // Set expiry
        await pipeline.KeyExpireAsync(key, window);

        await pipeline.ExecuteAsync();

        var current = (int)count;
        if (current > maxRequests)
        {
            _logger.LogWarning("Rate limit exceeded for {ApiKey}: {Count}/{Max}", apiKey, current, maxRequests);
            return false;
        }
        return true;
    }
}
